import{_ as n,K as i,a as l,c as p,ac as a,q as t}from"./chunks/framework.BSuaGltH.js";const C=JSON.parse('{"title":"Codex Token 计算规则","description":"输入、缓存、输出与推理 Token 的去重计量公式","frontmatter":{"title":"Codex Token 计算规则","description":"输入、缓存、输出与推理 Token 的去重计量公式","sources":[{"repository":"TeamDocs","file":"docs/engineering/codex/Token-Calculation.md"}],"showdocs":{"topics":[{"id":"ai","title":"AI 与 Codex","link":"/topics/ai/"}],"kind":"AI与Codex任务与配置","scope":"historical","audience":"general","group":"工程与工具","summary":"输入、缓存、输出与推理 Token 的去重计量公式","status":"active","related":[{"title":"AI与Codex：完整实践与解答","link":"/tools/ai/practice/application","kind":"AI与Codex完整实践与解答","scope":"general","audience":"general"},{"title":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"},{"title":"全局 AGENTS.md","link":"/tools/ai/guide/global-agents","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"AI辅助开发的任务、上下文与验收","link":"/tools/ai/assisted-development-workflow","kind":"AI与Codex上手与对象","scope":"general","audience":"general"},{"title":"Codex 插件用途与选择记录","link":"/tools/ai/reference/plugin","kind":"AI与Codex任务与配置","scope":"historical","audience":"general"}],"prev":{"text":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Codex 模型对比与选择","link":"/tools/ai/reference/model-selection"},"next":false},"headers":[],"relativePath":"tools/ai/reference/token-calculation.md","filePath":"tools/ai/reference/token-calculation.md"}'),o={name:"tools/ai/reference/token-calculation.md"};function d(h,s,r,k,c,u){const e=i("Mermaid");return l(),p("div",null,[s[0]||(s[0]=a(`<h1 id="codex-token-计算规则" tabindex="-1">Codex Token 计算规则 <a class="header-anchor" href="#codex-token-计算规则" aria-label="Permalink to &quot;Codex Token 计算规则&quot;">​</a></h1><blockquote><p>历史范围：本文保留来源记录中的模型系列、费率示例和界面名称，未将其核验为当前可用配置。计量方法与任务组织原则可参考；实际模型和价格请以文末官方入口及账号界面为准。</p></blockquote><blockquote><p>适用于 Codex CLI、IDE Extension、Codex App、Codex Cloud 和 OpenAI API。价格会变化，金额请以官方 Rate Card 为准。</p></blockquote><h2 id="一、核心公式" tabindex="-1">一、核心公式 <a class="header-anchor" href="#一、核心公式" aria-label="Permalink to &quot;一、核心公式&quot;">​</a></h2><p>设：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I = input_tokens</span></span>
<span class="line"><span>C = cached_input_tokens / cached_tokens</span></span>
<span class="line"><span>O = output_tokens</span></span>
<span class="line"><span>R = reasoning_tokens</span></span>
<span class="line"><span>T = total_tokens</span></span></code></pre></div><p>它们之间的关系是：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 ≤ C ≤ I</span></span>
<span class="line"><span>0 ≤ R ≤ O</span></span>
<span class="line"><span></span></span>
<span class="line"><span>非缓存输入 Token = I - C</span></span>
<span class="line"><span>总 Token = I + O</span></span></code></pre></div><p>按三档费率计算时：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>费用 =</span></span>
<span class="line"><span>    ((I - C) / 1,000,000 × 普通输入单价)</span></span>
<span class="line"><span>  + (C / 1,000,000 × 缓存输入单价)</span></span>
<span class="line"><span>  + (O / 1,000,000 × 输出单价)</span></span></code></pre></div><p>最容易算错的两点：</p><ul><li><code>cached_tokens</code> 已包含在 <code>input_tokens</code> 中，不能再加一次。</li><li><code>reasoning_tokens</code> 已包含在 <code>output_tokens</code> 中，不能再加一次。</li></ul>`,12)),t(e,{source:""}),s[1]||(s[1]=a(`<h2 id="二、token-是什么" tabindex="-1">二、Token 是什么 <a class="header-anchor" href="#二、token-是什么" aria-label="Permalink to &quot;二、Token 是什么&quot;">​</a></h2><p>Token 不是固定的字符或单词。一个 Token 可能是完整英文单词、词的一部分、标点、空格、换行、中文字符或代码片段。拆分方式取决于模型和编码器。</p><p>英文常用的粗略估算是：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 Token ≈ 4 个英文字符</span></span>
<span class="line"><span>1 Token ≈ 0.75 个英文单词</span></span>
<span class="line"><span>100 Tokens ≈ 75 个英文单词</span></span></code></pre></div><p>这些经验不能直接套用到中文、代码、JSON 或混合语言。字符数只能用于估算，准确数量应以服务端返回的 <code>usage</code> 为准。</p><h2 id="三、四类核心-token" tabindex="-1">三、四类核心 Token <a class="header-anchor" href="#三、四类核心-token" aria-label="Permalink to &quot;三、四类核心 Token&quot;">​</a></h2><h3 id="_1-input-tokens" tabindex="-1">1. Input Tokens <a class="header-anchor" href="#_1-input-tokens" aria-label="Permalink to &quot;1. Input Tokens&quot;">​</a></h3><p><code>input_tokens</code> 是某次模型调用实际处理的全部输入，不只是用户刚输入的文字，还可能包括：</p><ul><li>系统与 Codex 内置指令</li><li>对话历史和任务计划</li><li><code>AGENTS.md</code>、Skill 指令和工具定义</li><li>读取的源代码、配置、Git Diff</li><li>命令输出、测试日志和 MCP 返回数据</li><li>子代理结论、图片或文件处理结果</li><li>结构化输出 Schema</li></ul><p>因此，即使用户只输入一句话，Codex 实际输入也可能很大。</p><h3 id="_2-cached-input-tokens" tabindex="-1">2. Cached Input Tokens <a class="header-anchor" href="#_2-cached-input-tokens" aria-label="Permalink to &quot;2. Cached Input Tokens&quot;">​</a></h3><p><code>cached_tokens</code> 是 <code>input_tokens</code> 中命中 Prompt Cache 的部分：</p><div class="language-json vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;input_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;input_tokens_details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;cached_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这表示：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总输入              100,000</span></span>
<span class="line"><span>缓存输入             80,000</span></span>
<span class="line"><span>非缓存输入           20,000</span></span></code></pre></div><p>缓存输入通常费率更低，但不是免费。稳定的系统指令、工具定义和相同前缀更容易命中缓存；频繁变化的内容适合放在提示词后部。</p><h3 id="_3-output-tokens" tabindex="-1">3. Output Tokens <a class="header-anchor" href="#_3-output-tokens" aria-label="Permalink to &quot;3. Output Tokens&quot;">​</a></h3><p><code>output_tokens</code> 是模型生成的全部 Token，不等于最终屏幕上可见文字的 Token 数。它可能包含：</p><ul><li>最终回答、代码或补丁</li><li>工具调用名称和 JSON 参数</li><li>中间消息</li><li>Reasoning Token</li><li>消息边界、通道和格式等结构 Token</li></ul><p>因此，“最后只显示 200 字”不能推出“只产生约 200 个 Output Token”。</p><h3 id="_4-reasoning-tokens" tabindex="-1">4. Reasoning Tokens <a class="header-anchor" href="#_4-reasoning-tokens" aria-label="Permalink to &quot;4. Reasoning Tokens&quot;">​</a></h3><p>Reasoning Token 用于模型内部分析、规划、检查和决定工具调用。它是输出 Token 的子集：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reasoning_tokens ≤ output_tokens</span></span></code></pre></div><p>例如：</p><div class="language-json vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;usage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;input_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">75</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;input_tokens_details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cached_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;output_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1186</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;output_tokens_details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;reasoning_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;total_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1261</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>正确解读：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 Token                   75</span></span>
<span class="line"><span>输出 Token                1,186</span></span>
<span class="line"><span>其中 Reasoning Token      1,024</span></span>
<span class="line"><span>非 Reasoning 生成 Token     162</span></span>
<span class="line"><span>总 Token                  1,261</span></span></code></pre></div><p>但这 162 个 Token 不一定全部是最终可见回答，还可能包含工具调用或结构 Token。</p><h2 id="四、为什么一次-codex-任务会有多次计量" tabindex="-1">四、为什么一次 Codex 任务会有多次计量 <a class="header-anchor" href="#四、为什么一次-codex-任务会有多次计量" aria-label="Permalink to &quot;四、为什么一次 Codex 任务会有多次计量&quot;">​</a></h2><p>一次用户任务通常是 Agent 工作流，而不是一次模型调用：</p>`,30)),t(e,{source:""}),s[2]||(s[2]=a(`<p>每一轮都可能产生自己的 Input、Cached Input 和 Output Token。终端输出由工具产生时，不是模型 Output Token；但它在下一次模型调用中作为上下文进入模型，就会成为 Input Token。</p><p>因此：</p><ul><li>一条用户消息不等于一次模型请求。</li><li>一个 20 KB 的修改文件不等于 20 KB Output Token。</li><li>最终回答很短，也不代表整个 Agent 过程的 Output Token 很少。</li></ul><h2 id="五、codex-credits-计算" tabindex="-1">五、Codex Credits 计算 <a class="header-anchor" href="#五、codex-credits-计算" aria-label="Permalink to &quot;五、Codex Credits 计算&quot;">​</a></h2><p>Codex 订阅中的 Credits 与使用 API Key 产生的美元账单是两套计费账户，但都可以基于 Token 类型计算。</p><p>截至本文更新时间，官方 Codex Rate Card 展示的部分费率如下。该表是动态信息，使用前请查看<a href="https://help.openai.com/en/articles/20001106-codex-rate-card-2" target="_blank" rel="noopener noreferrer">最新官方费率</a>。</p><table tabindex="0"><thead><tr><th>模型</th><th style="text-align:right;">普通输入 / 1M</th><th style="text-align:right;">缓存输入 / 1M</th><th style="text-align:right;">输出 / 1M</th></tr></thead><tbody><tr><td>GPT-5.5</td><td style="text-align:right;">125 Credits</td><td style="text-align:right;">12.50 Credits</td><td style="text-align:right;">750 Credits</td></tr><tr><td>GPT-5.5 Cyber</td><td style="text-align:right;">500 Credits</td><td style="text-align:right;">50 Credits</td><td style="text-align:right;">3,000 Credits</td></tr><tr><td>GPT-5.4</td><td style="text-align:right;">62.50 Credits</td><td style="text-align:right;">6.25 Credits</td><td style="text-align:right;">375 Credits</td></tr><tr><td>GPT-5.4 Mini</td><td style="text-align:right;">18.75 Credits</td><td style="text-align:right;">1.875 Credits</td><td style="text-align:right;">113 Credits</td></tr><tr><td>GPT-5.3-Codex</td><td style="text-align:right;">43.75 Credits</td><td style="text-align:right;">4.375 Credits</td><td style="text-align:right;">350 Credits</td></tr></tbody></table><h3 id="计算示例" tabindex="-1">计算示例 <a class="header-anchor" href="#计算示例" aria-label="Permalink to &quot;计算示例&quot;">​</a></h3><p>假设 GPT-5.4 一次任务汇总后的用量是：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I = 100,000</span></span>
<span class="line"><span>C = 80,000</span></span>
<span class="line"><span>O = 5,000</span></span></code></pre></div><p>则：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>非缓存输入 = 100,000 - 80,000 = 20,000</span></span>
<span class="line"><span></span></span>
<span class="line"><span>普通输入费用 = 20,000 / 1,000,000 × 62.50 = 1.25 Credits</span></span>
<span class="line"><span>缓存输入费用 = 80,000 / 1,000,000 × 6.25  = 0.50 Credits</span></span>
<span class="line"><span>输出费用     =  5,000 / 1,000,000 × 375   = 1.875 Credits</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总费用 = 1.25 + 0.50 + 1.875 = 3.625 Credits</span></span></code></pre></div><p>如果 <code>O = 5,000</code> 中有 <code>R = 3,000</code>，仍然按 5,000 个 Output Token 计算，不能再加上 3,000。</p><h2 id="六、api-美元费用计算" tabindex="-1">六、API 美元费用计算 <a class="header-anchor" href="#六、api-美元费用计算" aria-label="Permalink to &quot;六、API 美元费用计算&quot;">​</a></h2><p>使用 API Key 时，公式完全相同，只需将 Credits 单价换成目标模型的美元单价：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API 费用（美元） =</span></span>
<span class="line"><span>    ((I - C) / 1,000,000 × 输入美元单价)</span></span>
<span class="line"><span>  + (C / 1,000,000 × 缓存输入美元单价)</span></span>
<span class="line"><span>  + (O / 1,000,000 × 输出美元单价)</span></span></code></pre></div><p>不要直接用 Codex Credits 表推导 API 美元价格；两者应分别查看 Codex Rate Card 和 <a href="https://developers.openai.com/api/docs/pricing" target="_blank" rel="noopener noreferrer">API Pricing</a>。</p><p>部分 API 工具还可能单独计费，例如 Web Search、文件存储、容器或其他托管工具。这些费用不一定包含在 Token 费用中。</p><h2 id="七、读取-responses-api-的-usage" tabindex="-1">七、读取 Responses API 的 Usage <a class="header-anchor" href="#七、读取-responses-api-的-usage" aria-label="Permalink to &quot;七、读取 Responses API 的 Usage&quot;">​</a></h2><p>典型的 Responses API 用量结构：</p><div class="language-json vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;usage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;input_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;input_tokens_details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;cached_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;output_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;output_tokens_details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;reasoning_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;total_tokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">105000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>通用计算伪代码：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uncachedInput = inputTokens - cachedInputTokens</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cost =</span></span>
<span class="line"><span>    uncachedInput / 1_000_000 * inputRate</span></span>
<span class="line"><span>  + cachedInputTokens / 1_000_000 * cachedInputRate</span></span>
<span class="line"><span>  + outputTokens / 1_000_000 * outputRate</span></span></code></pre></div><p>多次模型调用的 Agent 任务，应对每次调用分别计算后求和；不要只读取最终一次调用的 Usage。</p><h2 id="八、max-output-tokens-限制什么" tabindex="-1">八、<code>max_output_tokens</code> 限制什么 <a class="header-anchor" href="#八、max-output-tokens-限制什么" aria-label="Permalink to &quot;八、\`max_output_tokens\` 限制什么&quot;">​</a></h2><p><code>max_output_tokens</code> 限制模型本次调用最多能生成多少 Output Token，通常同时覆盖：</p><ul><li>Reasoning Token</li><li>可见回答</li><li>工具调用参数</li><li>其他生成结构 Token</li></ul><p>因此，限制过低时，模型可能在完成回答或工具调用前就耗尽输出预算。它不会限制 Input Token，也不会限制工具程序自己产生多少日志。</p><h2 id="九、七种常见误算" tabindex="-1">九、七种常见误算 <a class="header-anchor" href="#九、七种常见误算" aria-label="Permalink to &quot;九、七种常见误算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误计算</th><th>正确理解</th></tr></thead><tbody><tr><td><code>input + cached</code></td><td>Cached 已包含在 Input 中</td></tr><tr><td><code>output + reasoning</code></td><td>Reasoning 已包含在 Output 中</td></tr><tr><td>用最终回答长度估算全部 Output</td><td>Agent 可能有多次调用和不可见生成 Token</td></tr><tr><td>认为缓存会减少 Input 数</td><td>缓存改变计费档位，不改变本次报告的 Input 总量</td></tr><tr><td>认为一条用户消息只有一次调用</td><td>Codex 通常会在工具执行前后多次调用模型</td></tr><tr><td>用修改后文件大小估算 Output</td><td>补丁、工具调用和文件写入不能简单等同</td></tr><tr><td>把上下文窗口当成累计账单</td><td>上下文窗口是单次请求容量，账单是多次调用用量累计</td></tr></tbody></table><h2 id="十、如何降低-token-和-credits" tabindex="-1">十、如何降低 Token 和 Credits <a class="header-anchor" href="#十、如何降低-token-和-credits" aria-label="Permalink to &quot;十、如何降低 Token 和 Credits&quot;">​</a></h2><h3 id="降低-output-token" tabindex="-1">降低 Output Token <a class="header-anchor" href="#降低-output-token" aria-label="Permalink to &quot;降低 Output Token&quot;">​</a></h3><ul><li>简单任务使用较低 Reasoning Effort。</li><li>明确要求最终回答只包含改动、验证和风险。</li><li>避免重复解释已经确认的背景。</li><li>高风险任务才使用深度推理和并行 Agent。</li></ul><h3 id="降低-input-token" tabindex="-1">降低 Input Token <a class="header-anchor" href="#降低-input-token" aria-label="Permalink to &quot;降低 Input Token&quot;">​</a></h3><ul><li>指定文件、符号、错误和失败测试，不扫描整个仓库。</li><li>精简 <code>AGENTS.md</code>，任务专用流程放入按需加载的 Skill。</li><li>只启用任务所需的 MCP 和工具定义。</li><li>限制测试、终端和外部工具返回内容。</li><li>新主题新开会话，避免无关历史持续累积。</li></ul><h3 id="提高缓存命中" tabindex="-1">提高缓存命中 <a class="header-anchor" href="#提高缓存命中" aria-label="Permalink to &quot;提高缓存命中&quot;">​</a></h3><ul><li>保持系统指令、工具定义和稳定上下文的顺序不变。</li><li>固定内容放前面，动态任务内容放后面。</li><li>避免每轮无意义地改写相同长前缀。</li></ul><p>更多工程实践参见：<a href="/tools/ai/practice/token-usage">Codex Token 利用</a>。</p><h2 id="十一、项目成本预算" tabindex="-1">十一、项目成本预算 <a class="header-anchor" href="#十一、项目成本预算" aria-label="Permalink to &quot;十一、项目成本预算&quot;">​</a></h2><p>先按一段时间内所有调用汇总：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总普通输入 = Σ(input_tokens - cached_tokens)</span></span>
<span class="line"><span>总缓存输入 = Σ(cached_tokens)</span></span>
<span class="line"><span>总输出     = Σ(output_tokens)</span></span></code></pre></div><p>再套用对应模型费率。如果任务混用了多个模型，必须按模型分别汇总，最后再相加。</p><p>建议团队持续记录：</p><ul><li>每类任务的平均 Input、Cached Input 和 Output Token</li><li>缓存命中率 <code>C / I</code></li><li>每个任务平均 Credits</li><li>一次通过率和返工次数</li><li>模型、Reasoning Effort 与成本的关系</li></ul><p>只降低单次 Token、却增加返工次数，不是真正的成本优化。</p><h2 id="十二、速查表" tabindex="-1">十二、速查表 <a class="header-anchor" href="#十二、速查表" aria-label="Permalink to &quot;十二、速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>结论</th></tr></thead><tbody><tr><td>Cached Token 是否包含在 Input 中？</td><td>是</td></tr><tr><td>Reasoning Token 是否包含在 Output 中？</td><td>是</td></tr><tr><td>总 Token 如何计算？</td><td><code>Input + Output</code></td></tr><tr><td>缓存 Token 是否免费？</td><td>通常不是，只是费率更低</td></tr><tr><td>可见文字是否等于 Output Token？</td><td>否</td></tr><tr><td>终端输出是否是 Output Token？</td><td>工具生成时不是；下一轮被模型读取时是 Input</td></tr><tr><td>文件大小能否推算 Output Token？</td><td>不能准确推算</td></tr><tr><td>一条 Codex 消息是否只有一次模型调用？</td><td>通常不是</td></tr><tr><td>如何获得准确数字？</td><td>读取服务端<code>usage</code> 或 Codex Usage 页面</td></tr><tr><td>Credits 和 API 美元账单是否相同？</td><td>不是，应使用各自费率表</td></tr></tbody></table><h2 id="官方参考资料" tabindex="-1">官方参考资料 <a class="header-anchor" href="#官方参考资料" aria-label="Permalink to &quot;官方参考资料&quot;">​</a></h2><ul><li><a href="https://developers.openai.com/api/docs/guides/token-counting" target="_blank" rel="noopener noreferrer">Token counting</a></li><li><a href="https://help.openai.com/en/articles/4936856-what-are-tokens-and-how-to-count-them" target="_blank" rel="noopener noreferrer">What are tokens and how to count them?</a></li><li><a href="https://developers.openai.com/api/docs/guides/prompt-caching" target="_blank" rel="noopener noreferrer">Prompt caching</a></li><li><a href="https://developers.openai.com/api/docs/guides/reasoning" target="_blank" rel="noopener noreferrer">Reasoning models</a></li><li><a href="https://developers.openai.com/codex/pricing" target="_blank" rel="noopener noreferrer">Codex pricing</a></li><li><a href="https://help.openai.com/en/articles/20001106-codex-rate-card-2" target="_blank" rel="noopener noreferrer">Codex Rate Card</a></li><li><a href="https://developers.openai.com/api/docs/pricing" target="_blank" rel="noopener noreferrer">API pricing</a></li></ul>`,49))])}const E=n(o,[["render",d]]);export{C as __pageData,E as default};
